const SETTLED_TOPIC = "0x321f57f44af402708b8b3bad0bd10012cd568d8696946e26edeb86178bb7c27e";

const WEI_PER_TPOT = 10n ** 18n;

const WEI_PER_PLANCK = 10_000n;

const EVM_DECIMALS = 18;

/** Hashes recorded in this repo. Labels only — never treat these rows as a balance. */
