const MAX_LISTED_TABS = 40;

function uint256Word(value) {
  const n = typeof value === "bigint" ? value : BigInt(value);
  if (n < 0n) throw new Error("uint256 is negative");
  const hex = n.toString(16);
  if (hex.length > 64) throw new Error("uint256 overflow");
  return hex.padStart(64, "0");
}

function tabsCalldata(id) {
  return TABS_SELECTOR + uint256Word(id);
}

function remainingCalldata(id) {
  return REMAINING_SELECTOR + uint256Word(id);
}

function parseTabId(raw) {
  const text = String(raw).trim();
  if (!/^\d+$/.test(text)) throw new Error("Tab id must be a non-negative integer");
  const id = BigInt(text);
  if (id >= 2n ** 256n) throw new Error("Tab id does not fit in uint256");
  return id;
}

/** Format wei as a tPOT decimal string. Same truncation rules as sdk `formatTpot`. */
function formatTpot(wei, maxFrac = 6) {
  if (wei < 0n) throw new Error("wei is negative");
  if (maxFrac < 0 || maxFrac > EVM_DECIMALS) throw new Error("maxFrac out of range");
  const whole = wei / WEI_PER_TPOT;
  const fracFull = (wei % WEI_PER_TPOT).toString().padStart(EVM_DECIMALS, "0").slice(0, maxFrac);
  const frac = fracFull.replace(/0+$/, "");
  return frac.length ? `${whole.toString()}.${frac}` : whole.toString();
}

function isNativeToken(token) {
  return String(token).toLowerCase() === NATIVE;
}

function decodeUint256(data) {
  if (typeof data !== "string" || !/^0x[0-9a-fA-F]*$/.test(data) || data.length < 3) {
    throw new Error("RPC returned no uint word");
  }
  return BigInt(data);
}

function wordAt(hex, index) {
  const start = index * 64;
  const word = hex.slice(start, start + 64);
  if (word.length !== 64) throw new Error("RPC word is short");
  return word;
}

function addressFromWord(word) {
  return "0x" + word.slice(24);
}

/**
 * Decode `tabs(id)`. A zero payer means that id was never opened.
 * @returns {null | { payer: string, provider: string, token: string, deposit: bigint, claimed: bigint, expiry: bigint }}
 */
function decodeTab(data) {
  if (typeof data !== "string" || !data.startsWith("0x")) throw new Error("RPC returned no tab");
  const hex = data.slice(2);
  if (hex.length === 0) return null;
  if (hex.length < 64 * 6) throw new Error("tabs() return is short");
  const payer = addressFromWord(wordAt(hex, 0));
  if (isNativeToken(payer)) return null;
  return {
    payer,
    provider: addressFromWord(wordAt(hex, 1)),
    token: addressFromWord(wordAt(hex, 2)),
    deposit: BigInt("0x" + wordAt(hex, 3)),
    claimed: BigInt("0x" + wordAt(hex, 4)),
    expiry: BigInt("0x" + wordAt(hex, 5)),
  };
}

function topicAddress(topic) {
  if (typeof topic !== "string" || !/^0x[0-9a-fA-F]{64}$/.test(topic)) throw new Error("bad indexed address");
  return "0x" + topic.slice(-40);
}

function parseOpenedLog(log) {
  if (!log || !Array.isArray(log.topics) || log.topics.length < 4) throw new Error("Opened log is missing topics");
  const data = String(log.data || "").slice(2);
  if (data.length < 64 * 3) throw new Error("Opened log data is short");
  return {
    id: BigInt(log.topics[1]),
    payer: topicAddress(log.topics[2]),
    provider: topicAddress(log.topics[3]),
    token: addressFromWord(wordAt(data, 0)),
    amount: BigInt("0x" + wordAt(data, 1)),
    expiry: BigInt("0x" + wordAt(data, 2)),
    transactionHash: String(log.transactionHash || ""),
    blockNumber: BigInt(log.blockNumber),
  };
}

function parseSettledLog(log) {
  if (!log || !Array.isArray(log.topics) || log.topics.length < 2) throw new Error("Settled log is missing topics");
  const data = String(log.data || "").slice(2);
  if (data.length < 64 * 2) throw new Error("Settled log data is short");
  return {
    id: BigInt(log.topics[1]),
    paid: BigInt("0x" + wordAt(data, 0)),
    cumulative: BigInt("0x" + wordAt(data, 1)),
    transactionHash: String(log.transactionHash || ""),
    blockNumber: BigInt(log.blockNumber),
  };
}

function listedIds(nextId) {
  if (nextId <= 1n) return [];
  const last = nextId - 1n;
  const start = last > BigInt(MAX_LISTED_TABS) ? last - BigInt(MAX_LISTED_TABS) + 1n : 1n;
  const ids = [];
  for (let id = start; id <= last; id += 1n) ids.push(id);
  return ids;
}

async function rpcRequest(url, method, params, fetchImpl = globalThis.fetch) {
  const res = await fetchImpl(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }),
  });
  if (!res.ok) throw new Error(`RPC HTTP ${res.status}`);
  const body = await res.json();
  if (body.error) {
    const message = body.error.message || "RPC error";
    throw new Error(message);
  }
  return body.result;
}

function isLoopbackUrl(value) {
  let url;
  try {
    url = value instanceof URL ? value : new URL(value);
  } catch {
    return false;
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") return false;
  const host = url.hostname.replace(/^\[|\]$/g, "");
  return host === "127.0.0.1" || host === "localhost" || host === "::1";
}


const $ = (id) => document.getElementById(id);

const view = {
  now: null,
  blockNumber: null,
  nextId: null,
  rows: new Map(),
  opened: [],
  settled: [],
  logsNote: "",
  selected: null,
  txLookups: new Map(),
};

function text(el, value) {
  el.textContent = value;
}

function clear(el) {
  el.replaceChildren();
}

function shortAddr(value) {
  const hex = String(value || "");
  if (hex.length < 12) return hex;
  return `${hex.slice(0, 6)}…${hex.slice(-4)}`;
}

function formatUnix(seconds) {
  const n = Number(seconds);
  if (!Number.isFinite(n)) return String(seconds);
  return new Date(n * 1000).toISOString().replace(".000Z", "Z");
}

function formatDuration(seconds) {
  const n = Number(seconds);
  if (!Number.isFinite(n) || n < 0) return "";
  const days = Math.floor(n / 86400);
  const hours = Math.floor((n % 86400) / 3600);
  if (days > 0) return `${days}d ${hours}h`;
  const minutes = Math.floor((n % 3600) / 60);
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${minutes}m`;
}

function expiryPhrase(expiry) {
  const when = formatUnix(expiry);
  if (view.now === null) return `${when}. Latest block time was not available, so this page does not mark the tab expired.`;
  if (view.now >= expiry) return `${when}. Expired at chain time ${formatUnix(view.now)}.`;
  return `${when}. ${formatDuration(expiry - view.now)} left at chain time ${formatUnix(view.now)}.`;
}

function statusOf(tab) {
  if (!tab) return { kind: "quiet", label: "Empty" };
  if (view.now === null) return { kind: "quiet", label: "Unread clock" };
  if (view.now >= tab.expiry) return { kind: "expired", label: "Expired" };
  return { kind: "open", label: "Open" };
}

function amountNode(wei) {
  const wrap = document.createElement("div");
  wrap.className = "amt";
  const main = document.createElement("strong");
  main.textContent = `${formatTpot(wei)} tPOT`;
  const sub = document.createElement("span");
  let extra = `${wei.toString()} wei`;
  if (wei % WEI_PER_PLANCK === 0n) extra += ` · ${(wei / WEI_PER_PLANCK).toString()} planck`;
  sub.textContent = extra;
  wrap.append(main, sub);
  return wrap;
}

function badge(status) {
  const el = document.createElement("span");
  el.className = `badge ${status.kind}`;
  el.textContent = status.label;
  return el;
}

function hashLine(hash) {
  const wrap = document.createElement("div");
  wrap.className = "hash";
  const code = document.createElement("code");
  code.textContent = hash;
  const copy = document.createElement("button");
  copy.type = "button";
  copy.className = "ghost";
  copy.textContent = "Copy";
  copy.addEventListener("click", () => copyText(hash, copy));
  const link = document.createElement("a");
  link.href = EXPLORER_URL;
  link.target = "_blank";
  link.rel = "noreferrer";
  link.textContent = "Node console";
  link.title = "The console has no transaction route. Paste this hash under Network → events.";
  wrap.append(code, document.createTextNode(" "), copy, document.createTextNode(" "), link);
  return wrap;
}

async function copyText(value, button) {
  try {
    await navigator.clipboard.writeText(value);
    button.textContent = "Copied";
  } catch {
    button.textContent = "Copy failed";
  }
  setTimeout(() => {
    button.textContent = "Copy";
  }, 1200);
}

function setStatus(message, kind) {
  const el = $("rpc-status");
  text(el, message);
  if (kind) el.dataset.kind = kind;
  else delete el.dataset.kind;
}

function setBusy(busy) {
  for (const id of ["read-tab", "refresh", "probe"]) $(id).disabled = busy;
}

function rememberId(id) {
  const params = new URLSearchParams(location.search);
  if (id === null) params.delete("id");
  else params.set("id", id.toString());
  const next = params.toString();
  history.replaceState(null, "", next ? `?${next}` : location.pathname);
}

async function readChain() {
  const chainHex = await rpcRequest(RPC_URL, "eth_chainId", []);
  const chainId = Number(BigInt(chainHex));
  if (chainId !== CHAIN_ID) {
    throw new Error(`This RPC returned chain ${chainId}. The inspector only shows chain ${CHAIN_ID}, so no balances are listed.`);
  }
  const block = await rpcRequest(RPC_URL, "eth_getBlockByNumber", ["latest", false]);
  view.blockNumber = block && block.number ? BigInt(block.number) : null;
  view.now = block && block.timestamp ? BigInt(block.timestamp) : null;
  const nextHex = await rpcRequest(RPC_URL, "eth_call", [{ to: AGENT_TAB, data: NEXT_ID_SELECTOR }, "latest"]);
  view.nextId = decodeUint256(nextHex);
  view.opened = [];
  view.settled = [];
  view.logsNote = "";
  try {
    const opened = await rpcRequest(RPC_URL, "eth_getLogs", [{
      address: AGENT_TAB,
      fromBlock: "0x0",
      toBlock: "latest",
      topics: [OPENED_TOPIC],
    }]);
    const settled = await rpcRequest(RPC_URL, "eth_getLogs", [{
      address: AGENT_TAB,
      fromBlock: "0x0",
      toBlock: "latest",
      topics: [SETTLED_TOPIC],
    }]);
    if (!Array.isArray(opened) || !Array.isArray(settled)) throw new Error("eth_getLogs did not return a list");
    view.opened = opened.map(parseOpenedLog);
    view.settled = settled.map(parseSettledLog);
  } catch (err) {
    view.logsNote = err instanceof Error ? err.message : "eth_getLogs failed";
  }

  const ids = listedIds(view.nextId);
  const rows = await Promise.all(ids.map((id) => readTab(id)));
  view.rows = new Map(rows.map((row) => [row.id.toString(), row]));

  view.txLookups = new Map();
  await Promise.all(RECORDED_TXS.map(async (row) => {
    try {
      const tx = await rpcRequest(RPC_URL, "eth_getTransactionByHash", [row.hash]);
      view.txLookups.set(row.hash.toLowerCase(), tx ? "returned" : "null");
    } catch {
      view.txLookups.set(row.hash.toLowerCase(), "error");
    }
  }));
}

async function readTab(id) {
  const [tabHex, remainingHex] = await Promise.all([
    rpcRequest(RPC_URL, "eth_call", [{ to: AGENT_TAB, data: tabsCalldata(id) }, "latest"]),
    rpcRequest(RPC_URL, "eth_call", [{ to: AGENT_TAB, data: remainingCalldata(id) }, "latest"]),
  ]);
  return {
    id,
    tab: decodeTab(tabHex),
    remaining: decodeUint256(remainingHex),
  };
}

function renderList() {
  const body = $("tab-list");
  clear(body);
  const empty = $("list-empty");
  const ids = [...view.rows.keys()];
  empty.hidden = ids.length > 0;
  if (ids.length === 0) {
    empty.textContent = view.nextId === 1n
      ? "nextId is 1. The contract has no opened tab."
      : "The RPC did not return a tab list.";
  }
  for (const key of ids) {
    const row = view.rows.get(key);
    const tr = document.createElement("tr");
    if (view.selected === key) tr.setAttribute("aria-selected", "true");
    const idCell = document.createElement("td");
    const button = document.createElement("button");
    button.type = "button";
    button.className = "ghost";
    button.textContent = `Tab ${key}`;
    button.addEventListener("click", () => selectId(row.id, true));
    idCell.append(button);
    const provider = document.createElement("td");
    const remaining = document.createElement("td");
    const expiry = document.createElement("td");
    if (!row.tab) {
      provider.textContent = "—";
      remaining.textContent = "not open";
      expiry.textContent = "—";
    } else {
      provider.textContent = shortAddr(row.tab.provider);
      provider.title = row.tab.provider;
      remaining.append(amountNode(row.remaining));
      const state = statusOf(row.tab);
      expiry.append(badge(state), document.createTextNode(` ${formatUnix(row.tab.expiry)}`));
    }
    tr.append(idCell, provider, remaining, expiry);
    body.append(tr);
  }
}

function logsFor(id) {
  const key = id.toString();
  return {
    opened: view.opened.filter((log) => log.id.toString() === key),
    settled: view.settled.filter((log) => log.id.toString() === key),
  };
}

function renderDetail(row, error) {
  const pane = $("tab-detail");
  clear(pane);
  const title = document.createElement("h2");
  title.textContent = row ? `Tab ${row.id}` : "Tab";
  pane.append(title);
  if (error) {
    const p = document.createElement("p");
    p.className = "banner";
    p.dataset.kind = "error";
    p.textContent = error;
    pane.append(p);
    return;
  }
  if (!row || !row.tab) {
    const p = document.createElement("p");
    p.className = "empty";
    p.textContent = `No tab at id ${row ? row.id : "?"}. tabs() returned a zero payer, so there is no deposit to show.`;
    pane.append(p);
    return;
  }
  const tab = row.tab;
  const state = statusOf(tab);
  pane.append(badge(state));
  const dl = document.createElement("dl");
  const add = (label, node) => {
    const dt = document.createElement("dt");
    dt.textContent = label;
    const dd = document.createElement("dd");
    if (typeof node === "string") dd.textContent = node;
    else dd.append(node);
    dl.append(dt, dd);
  };
  add("Payer", tab.payer);
  add("Provider", tab.provider);
  add("Token", isNativeToken(tab.token) ? "Native tPOT (address 0)" : tab.token);
  add("Deposit", amountNode(tab.deposit));
  add("Claimed", amountNode(tab.claimed));
  add("Remaining", amountNode(row.remaining));
  const computed = tab.deposit - tab.claimed;
  if (computed !== row.remaining) {
    const warn = document.createElement("p");
    warn.className = "banner";
    warn.dataset.kind = "error";
    warn.textContent = `remaining() is ${row.remaining.toString()} wei, while deposit − claimed is ${computed.toString()} wei. Both figures are the RPC's.`;
    pane.append(warn);
  }
  add("Expiry", expiryPhrase(tab.expiry));
  const events = logsFor(row.id);
  const openHash = events.opened[0]?.transactionHash;
  add("Open tx", openHash ? hashLine(openHash) : "No Opened log for this id in the latest eth_getLogs result.");
  if (events.settled.length === 0) {
    add("Settle tx", "No Settled log for this id in the latest eth_getLogs result.");
  } else {
    const stack = document.createElement("div");
    for (const log of events.settled) stack.append(hashLine(log.transactionHash));
    add("Settle tx", stack);
  }
  const refund = document.createElement("p");
  refund.className = "note";
  refund.textContent = "Remaining is unspent escrow from remaining(). After expiry the payer may refund. This page does not send that transaction.";
  pane.append(dl, refund);
}

function renderLogs() {
  const body = $("log-txs");
  clear(body);
  const empty = $("log-empty");
  const rows = [
    ...view.opened.map((log) => ({ event: "Opened", ...log })),
    ...view.settled.map((log) => ({ event: "Settled", ...log })),
  ].sort((a, b) => (a.blockNumber < b.blockNumber ? -1 : a.blockNumber > b.blockNumber ? 1 : 0));
  empty.hidden = rows.length > 0 && !view.logsNote;
  if (rows.length === 0) {
    empty.hidden = false;
    empty.textContent = view.logsNote
      ? `eth_getLogs did not load (${view.logsNote}). Tab balances above still come from eth_call.`
      : "eth_getLogs returned no Opened or Settled events.";
  } else if (view.logsNote) {
    empty.hidden = false;
    empty.textContent = view.logsNote;
  }
  for (const log of rows) {
    const tr = document.createElement("tr");
    const event = document.createElement("td");
    event.textContent = log.event;
    const id = document.createElement("td");
    id.textContent = log.id.toString();
    const block = document.createElement("td");
    block.textContent = log.blockNumber.toString();
    const tx = document.createElement("td");
    tx.append(hashLine(log.transactionHash));
    tr.append(event, id, block, tx);
    body.append(tr);
  }
}

function renderRecorded() {
  const body = $("recorded");
  clear(body);
  const seen = new Set(
    [...view.opened, ...view.settled].map((log) => log.transactionHash.toLowerCase()),
  );
  for (const row of RECORDED_TXS) {
    const tr = document.createElement("tr");
    const label = document.createElement("td");
    label.textContent = row.label;
    const tab = document.createElement("td");
    tab.textContent = row.tabId === null ? "—" : String(row.tabId);
    const hash = document.createElement("td");
    hash.append(hashLine(row.hash));
    const source = document.createElement("td");
    source.textContent = row.source;
    const rpc = document.createElement("td");
    const lookup = view.txLookups.get(row.hash.toLowerCase());
    const inLogs = seen.has(row.hash.toLowerCase());
    if (lookup === "returned") rpc.textContent = inLogs ? "Transaction object returned, and the hash is in the logs." : "Transaction object returned.";
    else if (lookup === "error") rpc.textContent = "Lookup failed.";
    else if (inLogs) rpc.textContent = "eth_getTransactionByHash returned null. The hash is in the logs above.";
    else rpc.textContent = "eth_getTransactionByHash returned null. This hash is not an Opened or Settled log.";
    tr.append(label, tab, hash, source, rpc);
    body.append(tr);
  }
}

function renderChainMeta() {
  const block = view.blockNumber === null ? "block unavailable" : `block ${view.blockNumber.toString()}`;
  const time = view.now === null ? "time unavailable" : formatUnix(view.now);
  const next = view.nextId === null ? "nextId unavailable" : `nextId ${view.nextId.toString()}`;
  text($("chain-meta"), `Portaldot V3 · chain ${CHAIN_ID} · ${block} · ${time} · ${next}`);
}

function selectId(id, writeQuery) {
  view.selected = id.toString();
  $("tab-id").value = id.toString();
  if (writeQuery) rememberId(id);
  renderList();
  const row = view.rows.get(view.selected);
  if (row) renderDetail(row);
}

async function refresh(preferredId) {
  setBusy(true);
  setStatus(`Reading chain ${CHAIN_ID} from the public RPC…`);
  try {
    await readChain();
    renderChainMeta();
    const note = view.logsNote ? ` Log lookup: ${view.logsNote}.` : "";
    const head = view.blockNumber === null ? "latest block number missing" : `head block ${view.blockNumber.toString()}`;
    const want = preferredId ?? view.selected;
    if (want !== null && want !== undefined && /^\d+$/.test(String(want)) && !view.rows.has(String(want))) {
      try {
        const extra = await readTab(BigInt(want));
        view.rows.set(extra.id.toString(), extra);
      } catch {
        // The scanned list is still valid. The typed id is reported when the user hits Read.
      }
    }
    setStatus(`Read ${view.rows.size} tab slot${view.rows.size === 1 ? "" : "s"} at ${head}. nextId is ${view.nextId.toString()}.${note}`);
    if (want !== null && want !== undefined && view.rows.has(String(want))) selectId(BigInt(want), false);
    else if (view.rows.size) selectId(BigInt([...view.rows.keys()][0]), false);
    else {
      view.selected = null;
      renderList();
      const pane = $("tab-detail");
      clear(pane);
      const p = document.createElement("p");
      p.className = "empty";
      p.textContent = "No opened tab was returned. Type an id to read it directly.";
      pane.append(p);
    }
    renderLogs();
    renderRecorded();
  } catch (err) {
    view.rows = new Map();
    renderList();
    const message = err instanceof Error ? err.message : "The RPC did not answer.";
    setStatus(message, "error");
    $("list-empty").hidden = false;
    $("list-empty").textContent = "No balances are shown because the RPC read failed.";
    renderDetail(null, message);
    renderLogs();
    renderRecorded();
  } finally {
    setBusy(false);
  }
}

async function readTypedId(raw) {
  let id;
  try {
    id = parseTabId(raw);
  } catch (err) {
    renderDetail(null, err instanceof Error ? err.message : "Bad tab id");
    return;
  }
  setBusy(true);
  setStatus(`Reading tabs(${id.toString()})…`);
  try {
    const row = await readTab(id);
    view.rows.set(id.toString(), row);
    selectId(id, true);
    setStatus(`tabs(${id.toString()}) returned ${row.tab ? "an open tab" : "a zero payer"}.`);
  } catch (err) {
    const message = err instanceof Error ? err.message : "The tab read failed.";
    setStatus(message, "error");
    renderDetail({ id, tab: null, remaining: 0n }, message);
  } finally {
    setBusy(false);
  }
}

async function probeQuote(raw) {
  const out = $("probe-out");
  let url;
  try {
    url = new URL(raw.trim());
  } catch {
    out.textContent = "That gateway URL is not valid. No request was sent.";
    return;
  }
  if (!isLoopbackUrl(url)) {
    out.textContent = "This page only probes a gateway on localhost. For any other host, use curl from the steps above. No request was sent.";
    return;
  }
  if (url.pathname === "/" || url.pathname === "") url.pathname = "/quote";
  out.textContent = `Requesting ${url.href} …`;
  try {
    const res = await fetch(url.href, { method: "GET" });
    const bodyText = await res.text();
    let shown = bodyText;
    try {
      shown = JSON.stringify(JSON.parse(bodyText), null, 2);
    } catch {
      shown = bodyText || "(empty body)";
    }
    const required = res.headers.get("X-AgentTab-Required");
    const headerLine = required ? `X-AgentTab-Required: ${required}\n\n` : "";
    out.textContent = `HTTP ${res.status} ${res.statusText}\n${headerLine}${shown}`;
  } catch {
    out.textContent = [
      `No readable response from ${url.href}.`,
      "Start it on this machine with: npm run gateway",
      "A browser on another origin can read /quote only when the gateway sends Access-Control-Allow-Origin.",
      "Nothing was filled in from memory.",
    ].join("\n");
  }
}

function boot() {
  const params = new URLSearchParams(location.search);
  const initial = params.get("id");
  if (initial && /^\d+$/.test(initial)) $("tab-id").value = initial;
  $("read-form").addEventListener("submit", (event) => {
    event.preventDefault();
    readTypedId($("tab-id").value);
  });
  $("refresh").addEventListener("click", () => refresh($("tab-id").value.trim() || null));
  $("probe-form").addEventListener("submit", (event) => {
    event.preventDefault();
    probeQuote($("gateway-url").value);
  });
  refresh(initial && /^\d+$/.test(initial) ? initial : null);
}

boot();
